param([Parameter(Mandatory=$true)][string]$Executable,[Parameter(Mandatory=$true)][string]$Runtime,[Parameter(Mandatory=$true)][string]$NativeDirectory,[Parameter(Mandatory=$true)][string]$OutputDirectory)
$ErrorActionPreference='Stop';if(Test-Path $OutputDirectory){throw 'Fresh identity exports required'};$out=(New-Item -ItemType Directory $OutputDirectory).FullName;$exe=(Resolve-Path $Executable).Path;$runtimePath=(Resolve-Path $Runtime).Path
function FloatBytes([string]$Path){$tokens=(Get-Content $Path -Raw) -split '\s+'|Where-Object{$_ -ne ''};$n=[int]$tokens[0]*[int]$tokens[1];if($tokens.Count -ne $n+2){throw 'Bad native float count'};$stream=New-Object IO.MemoryStream;$writer=New-Object IO.BinaryWriter($stream);for($i=0;$i -lt $n;$i++){$writer.Write([single]::Parse($tokens[$i+2],[Globalization.CultureInfo]::InvariantCulture))};$writer.Flush();$data=$stream.ToArray();$writer.Dispose();return ,$data}
function Digest([byte[]]$Data){$sha=[Security.Cryptography.SHA256]::Create();return ([BitConverter]::ToString($sha.ComputeHash($Data))).Replace('-','')}
function Check([string]$Path,[byte[]]$Expected){if((Get-FileHash $Path).Hash -ne (Digest $Expected)){throw "Identity byte mismatch:$Path"}}
$records=@();foreach($pattern in @('asymmetric','impulse','hdr_ramp')){if(!(Test-Path "$NativeDirectory/$pattern/PASS.txt")){throw 'Missing native identity reference'};foreach($shape in @(@(80,96),@(96,80))){$h=$shape[0];$w=$shape[1];$orientation="h${h}_w${w}";$tag="${pattern}_$orientation";$native="$NativeDirectory/$pattern/$orientation";$ref=FloatBytes "$native/reference.txt";$test=FloatBytes "$native/test.txt";if((Digest $ref) -ne (Digest $test)){throw 'Native fixture is not identity'}
 $pfm="$out/$tag.pfm";$s=[IO.File]::Open($pfm,[IO.FileMode]::CreateNew);$b=New-Object IO.BinaryWriter($s);$b.Write([Text.Encoding]::ASCII.GetBytes("Pf`n$w $h`n-1.0`n"));for($y=$h-1;$y -ge 0;$y--){for($x=0;$x -lt $w;$x++){$b.Write([BitConverter]::ToSingle($ref,4*($y*$w+$x)))}};$b.Dispose()
 $output="$out/$tag";$ErrorActionPreference='Continue';& $exe --method HDRVDP3 --enable-validation --input $pfm --ref $pfm --hdrvdp3-runtime $runtimePath --hdrvdp3-export $output *> "$out/$tag.log";$code=$LASTEXITCODE;$ErrorActionPreference='Stop';if($code -ne 0 -or (Get-Content "$out/$tag.log" -Raw) -match 'VUID-|Validation Error|\[ERROR\]'){throw "Identity CLI failed:$tag"}
 Check "$output/input_reference.f32" $ref;Check "$output/input_test.f32" $test;Check "$output/reference_P.f32" (FloatBytes "$native/P_reference.txt");Check "$output/test_P.f32" (FloatBytes "$native/P_test.txt");Check "$output/log_adaptation.f32" (FloatBytes "$native/log_La.txt");Check "$output/scores.f32" (FloatBytes "$native/scores.txt")
 $scores=[IO.File]::ReadAllBytes("$output/scores.f32");if([BitConverter]::ToSingle($scores,0) -ne 10 -or [BitConverter]::ToSingle($scores,4) -ne 10){throw 'Identity score not10'}
 $base=(Get-Content "$native/base_selection.txt" -Raw) -split '\s+'|Where-Object{$_ -ne ''};if($base.Count -ne 6 -or $base[2] -ne '1' -or [double]$base[3] -ne 0 -or $base[5] -ne 'Inf'){throw 'Unexpected native identity base limit'}
 $q=(Get-Content "$output/quality.txt" -Raw) -split '\s+'|Where-Object{$_ -ne ''};if($q.Count -ne 8){throw 'Missing quality components'};foreach($i in 0..5){if([single]::Parse($q[$i],[Globalization.CultureInfo]::InvariantCulture) -ne 0){throw 'Nonzero identity band/total error'}}
 $records+=[pscustomobject]@{case=$tag;Q=10;Q_JOD=10;input_P_log_score_bits=$true;all_band_errors_zero=$true;native_base_frequency=0;native_base_noise='positive infinity'};$records|ConvertTo-Json|Set-Content "$out/results.json";Write-Output "$tag identity nativebits PASS"
}}
Get-FileHash -LiteralPath $exe,$PSCommandPath,"$runtimePath/pathway.runtime"|Select-Object Path,Hash|ConvertTo-Json|Set-Content "$out/hashes.json"
Set-Content "$out/PASS.txt" 'Six identity PFM pairs:native input/P/log/score bits exact;all band/total errors zero;Q=Q_JOD=10;native0frequency/+Infnoise limit exercised;no Vulkan errors.'
